using System.Text;
using Microsoft.CodeAnalysis;

namespace Injectra.Godot.Generation;

internal static class InjectionSourceEmitter
{
	internal static string Emit(INamedTypeSymbol type, IReadOnlyList<IMethodSymbol> methods)
	{
		var target = Name(type);
		var calls = string.Join("\n\n", methods.Select(EmitCall));
		var namespaceLine = type.ContainingNamespace.IsGlobalNamespace ? "" : $"namespace {type.ContainingNamespace.ToDisplayString()};\n\n";
		var source = $$"""
			// <auto-generated/>
			#nullable enable
			#pragma warning disable CS0612, CS0618
			{{namespaceLine}}partial class @{{type.Name}} : global::Injectra.Godot.Generation.IGeneratedInjectable
			{
				bool global::Injectra.Godot.Generation.IGeneratedInjectable.TryInject(global::System.Type runtimeType, global::Injectra.IResolver resolver)
				{
					if (runtimeType != typeof({{target}}))
						return false;

			{{Indent(calls, 2)}}
					return true;
				}
			}
			""";
		return source.Replace("\r\n", "\n") + "\n";
	}

	private static string EmitCall(IMethodSymbol method)
	{
		var declaring = Name(method.ContainingType);
		var dependencies = new StringBuilder();
		for (var i = 0; i < method.Parameters.Length; i++)
		{
			var dependency = Name(method.Parameters[i].Type);
			dependencies.AppendLine($$"""
				{{dependency}} argument{{i}};
				try
				{
					argument{{i}} = resolver.Resolve<{{dependency}}>();
				}
				catch (global::System.Exception error)
				{
					throw new global::Injectra.Godot.InjectionException(
						$"Cannot resolve {typeof({{dependency}})} for {typeof({{declaring}})}.{{method.Name}} on {runtimeType}.", error);
				}
				""");
		}
		var arguments = string.Join(", ", Enumerable.Range(0, method.Parameters.Length).Select(index => $"argument{index}"));
		return $$"""
			{
			{{Indent(dependencies.ToString(), 1)}}
				try
				{
					(({{declaring}})this).@{{method.Name}}({{arguments}});
				}
				catch (global::System.Exception error)
				{
					throw new global::Injectra.Godot.InjectionException(
						$"Injection method {typeof({{declaring}})}.{{method.Name}} on {runtimeType} failed.", error);
				}
			}
			""";
	}

	private static string Name(ITypeSymbol type) => type.TypeKind == TypeKind.Dynamic
		? "global::System.Object" : type.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);

	private static string Indent(string source, int depth)
	{
		if (source.Length == 0)
			return "";
		var prefix = new string('\t', depth);
		return prefix + source.TrimEnd().Replace("\n", "\n" + prefix);
	}
}
